    int codePoint = 0;
    int codePointLength = 0;

    // Check if the first byte is the start of a UTF-8 character
    if ((bb.getByte(index) & 0b11111000) == 0b11110000) {
        // 3-byte encoding
        codePoint = (bb.getByte(index) & 0b00000111) << 12;
        codePoint |= (bb.getByte(index + 1) & 0b11111100) << 6;
        codePoint |= bb.getByte(index + 2) & 0b11111111;
        codePointLength = 3;
    } else if ((bb.getByte(index) & 0b11110000) == 0b11100000) {
        // 2-byte encoding
        codePoint = (bb.getByte(index) & 0b00001111) << 6;
        codePoint |= bb.getByte(index + 1) & 0b11111111;
        codePointLength = 2;
    } else if ((bb.getByte(index) & 0b10000000) == 0b00000000) {
        // 1-byte encoding
        codePoint = bb.getByte(index) & 0b01111111;
        codePointLength = 1;
    }

    // Check if the code point is valid
    if (Character.isValidCodePoint(codePoint)) {
        sb.append(Character.charAt(codePoint));
    } else {
        // Invalid code point, insert a replacement character
        sb.append('\uFFFD');
    }

    return index + codePointLength;
}

