	if (path == null || path.isEmpty()) {
		return pathSegments;
	}
	path = path.replaceFirst("/", ""); // remove leading '/'
	String[] pathSections = path.split("/");
	for (String pathSection : pathSections) {
		if (decode) {
			pathSection = removeOddCharacters(pathSection);
		}
		pathSegments.add(new PathSegmentImpl(pathSection));
	}
	return pathSegments;
